import sys,re
N=sys.argv[1]
st={}
for f in ['research_notes/Практики CRM в крупных компаниях/link_check.tsv','research_notes/Доказательная база для CRM кейса/link_check.tsv']:
    for l in open(f,encoding='utf-8'):
        if '\t' in l: c,u=l.strip().split('\t'); st[u]=c
open(f'{N}/known_urls.txt','w').write('\n'.join(sorted(st))+'\n')
main=''
for r in ['reports/Практики CRM в крупных компаниях.md','reports/Доказательная база для CRM кейса.md']:
    t=open(r,encoding='utf-8').read(); main+=t.split('## Библиотека ссылок')[0]
blocked=[u for u,c in st.items() if c not in ('200','404')]
cited=[u for u in blocked if u in main]
rest=[u for u in blocked if u not in main]
with open(f'{N}/blocked_known.tsv','w') as f:
    for u in cited: f.write(f'priority\t{st[u]}\t{u}\n')
    for u in rest: f.write(f'library_only\t{st[u]}\t{u}\n')
print('known',len(st),'| blocked',len(blocked),'| cited in text',len(cited),'| library only',len(rest))
EOF

