  --accent: #4d8dff; --accent-ink: #84b2ff; --accent-soft: #1b2c55; --accent-soft-2: #22376a;
  --pink: #3a2443; --peach: #3e2c25; --yellow: #3a3420;
  --ok: #4cc27f; --ok-bg: #163526; --warn: #f2b04c; --warn-bg: #3a2b12; --bad: #ff7088; --bad-bg: #3e1b26;
  --code-bg: #121b33; --shadow: 0 2px 12px rgba(0, 0, 0, .35);
  color-scheme: dark;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 400 var(--fs-ui)/var(--lh-ui) var(--font);
  -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility;
  font-kerning: normal; font-variant-ligatures: common-ligatures;
  overflow-x: hidden;
}
a { color: var(--accent-ink); text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.wrap { max-width: 1160px; margin: 0 auto; padding-inline: var(--gutter); }

/* header */
.brand-band { height: 6px; background: linear-gradient(90deg, var(--pink), var(--peach) 35%, var(--yellow) 62%, var(--accent-soft-2)); }
.masthead-outer { background: var(--surface); }
.masthead { padding-block: clamp(24px, 16px + 3vw, 48px) 24px; display: grid; gap: 12px; }
.eyebrow { margin: 0; font: 700 var(--fs-caption)/var(--lh-caption) var(--font); letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }
.masthead h1 { margin: 0; font: 900 var(--fs-hero)/1.1 var(--font); letter-spacing: -.01em; color: var(--ink-strong); max-width: 22ch; text-wrap: balance; }
.masthead .lead { margin: 0; max-width: 62ch; font-size: var(--fs-read); line-height: var(--lh-read); color: var(--ink); text-wrap: pretty; }
.meta { display: flex; flex-wrap: wrap; gap: 8px; margin: 4px 0 0; padding: 0; list-style: none; }
.meta li { font: 700 var(--fs-small)/var(--lh-small) var(--font); padding: 6px 12px; border-radius: var(--radius-ctl); background: var(--bg); color: var(--ink); font-variant-numeric: tabular-nums; }

/* main tabs */
.bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; background: var(--surface); border-bottom: 1px solid var(--line); box-shadow: var(--shadow); }
.tabs { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab {
  position: relative; flex: none; border: 0; background: none; cursor: pointer; white-space: nowrap;
  font: 400 var(--fs-ui)/var(--lh-ui) var(--font); color: var(--ink); padding: 16px 12px 14px;
  transition: color var(--duration) var(--ease);
}
.tab::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 3px; border-radius: 3px 3px 0 0; background: var(--accent); transform: scaleX(0); transition: transform var(--duration) var(--ease); }
.tab:hover { color: var(--accent-ink); }
.tab[aria-selected="true"] { font-weight: 700; color: var(--ink-strong); }
.tab[aria-selected="true"]::after { transform: scaleX(1); }

/* panels and sub tabs */
main { padding-block: 8px 64px; }
.panel { padding-top: 16px; }
.topic-title { margin: 8px 0 12px; font: 700 var(--fs-small)/var(--lh-small) var(--font); color: var(--muted); }
.topic-note { margin: 0 0 12px; padding: 12px 16px; border-radius: var(--radius-block); background: var(--peach); max-width: var(--measure); font-size: var(--fs-small); line-height: var(--lh-small); text-wrap: pretty; }
.topic-note::before { content: "Требование кейса. "; font-weight: 700; }
.subtabs { position: sticky; top: var(--bar-h); z-index: 10; display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; padding-block: 12px; margin-bottom: 4px; background: var(--bg); }
.subtabs::-webkit-scrollbar { display: none; }
.subtabs.single { display: none; }
.subtab {
  flex: none; cursor: pointer; white-space: nowrap; display: inline-flex; align-items: center;
  font: 700 var(--fs-small)/var(--lh-small) var(--font); color: var(--ink);
  padding: 8px 14px; border-radius: var(--radius-ctl); border: 1px solid var(--line); background: var(--surface);
  transition: background var(--duration) var(--ease), color var(--duration) var(--ease), border-color var(--duration) var(--ease);
}
.subtab:hover { border-color: var(--accent); color: var(--accent-ink); }
.subtab[aria-selected="true"] { background: var(--accent-soft); color: var(--accent-ink); border-color: transparent; }
.dot { width: 8px; height: 8px; border-radius: 50%; margin-right: 8px; flex: none; }
.dot-strong { background: var(--ok); }
.dot-mid { background: var(--warn); }
.dot-weak { background: var(--bad); }

.subpanel { background: var(--surface); border-radius: var(--radius-card); box-shadow: var(--shadow); padding: clamp(20px, 12px + 2vw, 40px); }
.subpanel-title { margin: 0 0 16px; font: 700 var(--fs-h2)/var(--lh-h2) var(--font); color: var(--ink-strong); max-width: 30ch; text-wrap: balance; }
.case-q { margin: 0 0 24px; padding: 14px 18px; border-radius: var(--radius-block); background: var(--pink); max-width: var(--measure); }
.case-q-label { display: block; margin-bottom: 4px; font: 700 var(--fs-caption)/var(--lh-caption) var(--font); letter-spacing: .06em; text-transform: uppercase; color: var(--ink); opacity: .75; }
.case-q p { margin: 0; font: 700 var(--fs-read)/1.5 var(--font); color: var(--ink-strong); text-wrap: pretty; }

/* reading typography */
.prose { font-size: var(--fs-read); line-height: var(--lh-read); color: var(--ink); hyphens: auto; -webkit-hyphens: auto; hanging-punctuation: first; }
.prose > * { max-width: var(--measure); }
.prose > .table-wrap, .prose > pre { max-width: none; }
.prose p { margin: 0 0 16px; text-wrap: pretty; }
.prose h3 { margin: 40px 0 12px; font: 700 var(--fs-h3)/var(--lh-h3) var(--font); color: var(--ink-strong); text-wrap: balance; hyphens: manual; }
.prose h4 { margin: 28px 0 8px; font: 700 var(--fs-read)/24px var(--font); color: var(--ink-strong); text-wrap: balance; hyphens: manual; }
.prose h3:first-child, .prose h4:first-child { margin-top: 0; }
.prose ul, .prose ol { margin: 0 0 16px; padding-left: 24px; }
.prose li { margin: 6px 0; padding-left: 2px; text-wrap: pretty; }
.prose li::marker { color: var(--accent); font-weight: 700; }
.prose strong { font-weight: 700; color: var(--ink-strong); }
.prose em { font-style: italic; }
.prose code { font: .85em/1 var(--mono); background: var(--code-bg); padding: 2px 6px; border-radius: var(--radius-chip); }
.prose pre { margin: 8px 0 24px; padding: 16px 20px; background: var(--code-bg); border-radius: var(--radius-block); overflow-x: auto; }
.prose pre code { background: none; padding: 0; font-size: 13.5px; line-height: 1.6; }
.prose blockquote { margin: 0 0 16px; padding: 4px 0 4px 16px; border-left: 3px solid var(--accent-soft-2); color: var(--muted); }
.prose hr { border: 0; border-top: 1px solid var(--line); margin: 32px 0; }
.topic-intro { margin-bottom: 8px; }

/* citations as quiet chips */
.cites { display: inline; }
a.cite {
  display: inline; font: 700 13px/1 var(--font); color: var(--muted); background: var(--bg);
  padding: 3px 7px; border-radius: var(--radius-chip); white-space: normal; hyphens: manual;
  box-decoration-break: clone; -webkit-box-decoration-break: clone;
  transition: background var(--duration) var(--ease), color var(--duration) var(--ease);
}
a.cite + a.cite { margin-left: 4px; }
a.cite:hover { text-decoration: none; background: var(--accent-soft); color: var(--accent-ink); }
td a.cite { line-height: 1.9; }

/* tables */
.table-wrap { overflow-x: auto; margin: 8px 0 24px; border: 1px solid var(--line); border-radius: var(--radius-block); background: var(--surface); }
table { border-collapse: collapse; width: 100%; min-width: 40rem; font-size: var(--fs-small); line-height: var(--lh-small); font-variant-numeric: tabular-nums; hyphens: auto; -webkit-hyphens: auto; }
th, td { text-align: left; vertical-align: top; padding: 10px 14px; border-bottom: 1px solid var(--line); min-width: 7rem; }
th:first-child, td:first-child { min-width: 3.5rem; }
th { font: 700 13px/18px var(--font); color: var(--muted); background: var(--bg); }
tbody tr:last-child td { border-bottom: 0; }
tbody tr:hover td { background: color-mix(in srgb, var(--accent-soft) 50%, transparent); }
td a { overflow-wrap: anywhere; }

.st { font-weight: 700; }
.st-ok { color: var(--ok); }
.st-warn { color: var(--warn); }
.st-bad { color: var(--bad); }
.lvl { display: inline-block; font: 700 var(--fs-caption)/var(--lh-caption) var(--font); padding: 3px 8px; border-radius: var(--radius-chip); white-space: nowrap; }
.lvl-strong { background: var(--ok-bg); color: var(--ok); }
.lvl-mid { background: var(--warn-bg); color: var(--warn); }
.lvl-weak { background: var(--bad-bg); color: var(--bad); }

/* third round */
.delta { margin: 0 0 32px; padding: clamp(16px, 12px + 1vw, 24px); border-radius: var(--radius-block); background: linear-gradient(160deg, var(--accent-soft), var(--surface) 70%); border: 1px solid var(--accent-soft-2); }
.delta-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 8px; }
.delta-label { font: 700 var(--fs-caption)/var(--lh-caption) var(--font); padding: 4px 8px; border-radius: var(--radius-chip); background: var(--accent); color: #fff; }
.delta-move { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: var(--fs-small); }
.delta-title { margin: 4px 0 16px; font: 700 var(--fs-h3)/var(--lh-h3) var(--font); color: var(--ink-strong); max-width: var(--measure); text-wrap: balance; }
.earlier-label { display: flex; align-items: center; gap: 12px; margin: 0 0 20px; font: 700 var(--fs-small)/var(--lh-small) var(--font); color: var(--muted); }
.earlier-label::after { content: ""; flex: 1; height: 1px; background: var(--line); }

/* pager */
.pager { display: flex; justify-content: space-between; gap: 12px; margin-top: 40px; padding-top: 20px; border-top: 1px solid var(--line); }
.pager-btn { cursor: pointer; max-width: 48%; text-align: left; font: 700 var(--fs-small)/var(--lh-small) var(--font); color: var(--accent-ink); background: var(--accent-soft); border: 0; border-radius: var(--radius-ctl); padding: 10px 16px; transition: background var(--duration) var(--ease); }
.pager-btn.next { margin-left: auto; text-align: right; }
.pager-btn:hover { background: var(--accent-soft-2); }

/* library */
.lib-tools { position: sticky; top: var(--bar-h); z-index: 10; display: grid; gap: 10px; padding-block: 12px 8px; background: var(--bg); }
.search input { width: 100%; height: 44px; padding: 0 14px; font: 400 var(--fs-ui) var(--font); color: var(--ink); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-ctl); }
.search input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.chips { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; }
.chips::-webkit-scrollbar { display: none; }
.chip { flex: none; white-space: nowrap; cursor: pointer; font: 700 var(--fs-small)/var(--lh-small) var(--font); padding: 8px 14px; border-radius: var(--radius-ctl); border: 1px solid var(--line); background: var(--surface); color: var(--ink); transition: background var(--duration) var(--ease), color var(--duration) var(--ease); }
.chip:hover { border-color: var(--accent); }
.chip[aria-pressed="true"] { background: var(--accent-soft); color: var(--accent-ink); border-color: transparent; }
.lib-count { margin: 0; font: 400 var(--fs-small)/var(--lh-small) var(--font); color: var(--muted); font-variant-numeric: tabular-nums; }
.legend { margin: 8px 0 20px; padding: 14px 18px; border-radius: var(--radius-block); background: var(--surface); }
.legend summary { cursor: pointer; font-weight: 700; }
.legend > :not(summary) { margin-top: 10px; max-width: var(--measure); font-size: var(--fs-small); line-height: 22px; }
.lib-block h2 { margin: 32px 0 8px; font: 700 var(--fs-h3)/var(--lh-h3) var(--font); color: var(--ink-strong); }
.lib-block h2 .n { margin-left: 6px; font: 700 var(--fs-small) var(--font); color: var(--muted); }
.lib-block > p { max-width: var(--measure); color: var(--muted); font-size: var(--fs-small); line-height: 22px; }

footer { padding-block: 24px 40px; color: var(--muted); font-size: var(--fs-small); line-height: 22px; border-top: 1px solid var(--line); }

@media (max-width: 600px) {
  :root { --fs-read: 16px; --lh-read: 26px; }
  .subpanel { border-radius: var(--radius-block); }
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; scroll-behavior: auto !important; }
}
@media print {
  .bar, .subtabs, .pager, .lib-tools, .brand-band { display: none; }
  .panel[hidden], .subpanel[hidden] { display: block !important; }
  .subpanel { box-shadow: none; padding: 0; margin-bottom: 32px; }
}
