<body>
<div class="masthead-outer">
  <div class="brand-band" aria-hidden="true"></div>
  <header class="masthead wrap">
    <p class="eyebrow">Исследование для CRM-кейса · 01.10.2026</p>
    <h1>CRM в крупных компаниях: доказательная база для кейса</h1>
    <p class="lead">Три круга исследования в одном месте. Вкладки 1–4 повторяют блоки кейса. В каждом подвопросе сверху новое из третьего круга и сила базы «было → стало», ниже то, что собрано раньше. Цветная точка на вкладке показывает текущую силу базы.</p>
    <ul class="meta">
      <li>Окно: 10.2023 – 10.2026</li>
      <li>{{N_LINKS}} ссылок</li>
      <li>Ссылки проверены скриптом и браузером</li>
    </ul>
  </header>
</div>
<div class="bar" id="bar">
  <nav class="wrap tabs" role="tablist" aria-label="Разделы исследования">
{{NAV}}
  </nav>
</div>
<main class="wrap" id="main">
{{PANELS}}
</main>
<footer class="wrap">Метки источников: П — сама компания, С — научная статья или патент, Д — официальная документация или закон, В — вендор или агентство, Т — пресса, вакансия или пересказ, «фон» — до октября 2023. ✓ ссылка открывается, ⚠ сайт блокирует автопроверку, ✗ не открывается.</footer>
<script>
(() => {
  const tabs = [...document.querySelectorAll('.tab')];
  const panels = [...document.querySelectorAll('.panel')];
  const bar = document.getElementById('bar');
  const main = document.getElementById('main');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const lastSub = {};

  const setBarHeight = () => document.documentElement.style.setProperty('--bar-h', bar.offsetHeight + 'px');
  setBarHeight();
  new ResizeObserver(setBarHeight).observe(bar);

  function scrollToContent() {
    const top = main.getBoundingClientRect().top + window.scrollY - bar.offsetHeight;
    if (window.scrollY > top) window.scrollTo({ top, behavior: reduce ? 'auto' : 'smooth' });
  }

  function activate(ti, si, opts = {}) {
    ti = Math.max(0, Math.min(ti, tabs.length - 1));
    tabs.forEach((t, i) => {
      const on = i === ti;
      t.setAttribute('aria-selected', on);
      t.tabIndex = on ? 0 : -1;
      panels[i].hidden = !on;
    });
    tabs[ti].parentElement.scrollLeft = tabs[ti].offsetLeft - 16;
    const subs = [...panels[ti].querySelectorAll('.subtab')];
    const subPanels = [...panels[ti].querySelectorAll('.subpanel')];
    let hash = '#t' + ti;
    if (subs.length) {
      si = Math.max(0, Math.min(si ?? lastSub[ti] ?? 0, subs.length - 1));
      lastSub[ti] = si;
      subs.forEach((b, i) => {
        const on = i === si;
        b.setAttribute('aria-selected', on);
        b.tabIndex = on ? 0 : -1;
        subPanels[i].hidden = !on;
      });
      subs[si].parentElement.scrollLeft = subs[si].offsetLeft - 16;
      hash += '.s' + si;
    }
    if (location.hash !== hash) history.replaceState(null, '', hash);
    if (opts.scroll) scrollToContent();
    if (opts.focus) opts.focus.focus();
  }

  function arrowNav(list, e, onPick) {
    const i = list.indexOf(e.target);
    if (i < 0) return;
    const map = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: list.length - 1 };
    if (!(e.key in map)) return;
    e.preventDefault();
    const next = (map[e.key] + list.length) % list.length;
    onPick(next, list[next]);
  }

  tabs.forEach((t, i) => t.addEventListener('click', () => activate(i, undefined, { scroll: true })));
  tabs[0].parentElement.addEventListener('keydown', e => arrowNav(tabs, e, (n, el) => activate(n, undefined, { focus: el })));

  panels.forEach((p, ti) => {
    const subs = [...p.querySelectorAll('.subtab')];
    subs.forEach((b, si) => b.addEventListener('click', () => activate(ti, si, { scroll: true })));
    const list = p.querySelector('.subtabs');
    if (list) list.addEventListener('keydown', e => arrowNav(subs, e, (n, el) => activate(ti, n, { focus: el })));
    p.querySelectorAll('.pager-btn').forEach(b => b.addEventListener('click', () => activate(ti, +b.dataset.go, { scroll: true })));
  });

  function fromHash() {
    const m = location.hash.match(/^#t(\d+)(?:\.s(\d+))?$/);
    if (m) activate(+m[1], m[2] === undefined ? undefined : +m[2]);
    else activate(0, 0);
  }
  window.addEventListener('hashchange', fromHash);
  fromHash();

  const q = document.getElementById('lib-q');
  if (q) {
    const libPanel = q.closest('.panel');
    const rows = [...libPanel.querySelectorAll('.lib-block tbody tr')];
    const count = document.getElementById('lib-count');
    const chips = [...libPanel.querySelectorAll('.chip')];
    let status = 'all';
    rows.forEach(r => {
      r.dataset.text = r.textContent.toLowerCase();
      const last = r.lastElementChild;
      r.dataset.st = last.querySelector('.st-bad') ? 'bad' : last.querySelector('.st-warn') ? 'warn' : last.querySelector('.st-ok') ? 'ok' : 'other';
    });
    const apply = () => {
      const s = q.value.trim().toLowerCase();
      let shown = 0;
      rows.forEach(r => {
        const ok = (!s || r.dataset.text.includes(s)) && (status === 'all' || r.dataset.st === status);
        r.hidden = !ok;
        if (ok) shown++;
      });
      count.textContent = `Показано ${shown} из ${rows.length}`;
    };
    q.addEventListener('input', apply);
    chips.forEach(c => c.addEventListener('click', () => {
      status = c.dataset.st;
      chips.forEach(x => x.setAttribute('aria-pressed', x === c));
      apply();
    }));
    apply();
  }
})();
</script>
