<style>
:root {
  --paper: #f5f3ee;
  --surface: #ffffff;
  --ink: #15171c;
  --muted: #5b606a;
  --line: #ddd8cd;
  --accent: #0f5c56;
  --accent-soft: #e3efec;
  --ok: #1d7446;
  --warn: #9a5800;
  --bad: #b42318;
  --ok-bg: #e2f2e8;
  --warn-bg: #fbeed8;
  --bad-bg: #fbe4e1;
  --code-bg: #eeebe3;
  --shadow: 0 1px 0 rgba(21, 23, 28, .04), 0 8px 24px -12px rgba(21, 23, 28, .18);

  --font-sans: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --text-base: clamp(1rem, .96rem + .2vw, 1.0625rem);
  --text-small: .875rem;
  --text-hero: clamp(2rem, 1.2rem + 3.2vw, 3.5rem);
  --text-title: clamp(1.45rem, 1.15rem + 1.2vw, 2.1rem);

  --gutter: 16px;
  --measure: 74ch;
  --bar-h: 56px;
  --duration: 180ms;
  --ease: cubic-bezier(.16, 1, .3, 1);
}
@media (min-width: 720px) { :root { --gutter: 32px; } }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --paper: #111316; --surface: #181b20; --ink: #ecebe6; --muted: #a3a7af; --line: #2d3138;
    --accent: #62c6b8; --accent-soft: #15312d; --ok: #5cc68c; --warn: #f0b24c; --bad: #f47b6f;
    --ok-bg: #143223; --warn-bg: #3a2a10; --bad-bg: #3d1a17; --code-bg: #1d2127;
    --shadow: 0 1px 0 rgba(0, 0, 0, .3), 0 8px 24px -12px rgba(0, 0, 0, .6);
  }
}
:root[data-theme="dark"] {
  --paper: #111316; --surface: #181b20; --ink: #ecebe6; --muted: #a3a7af; --line: #2d3138;
  --accent: #62c6b8; --accent-soft: #15312d; --ok: #5cc68c; --warn: #f0b24c; --bad: #f47b6f;
  --ok-bg: #143223; --warn-bg: #3a2a10; --bad-bg: #3d1a17; --code-bg: #1d2127;
  --shadow: 0 1px 0 rgba(0, 0, 0, .3), 0 8px 24px -12px rgba(0, 0, 0, .6);
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--paper); color: var(--ink);
  font: 400 var(--text-base)/1.6 var(--font-sans);
  overflow-x: hidden;
}
a { color: var(--accent); text-underline-offset: 2px; text-decoration-thickness: 1px; }
a:hover { text-decoration-thickness: 2px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.wrap { max-width: 1180px; margin: 0 auto; padding-inline: var(--gutter); }

/* header */
.masthead { padding-block: clamp(1.5rem, 1rem + 3vw, 3.5rem) 1.25rem; }
.eyebrow { font: 500 .75rem/1 var(--font-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--accent); margin: 0 0 1rem; }
.masthead h1 { font-size: var(--text-hero); line-height: 1.04; letter-spacing: -.025em; font-weight: 700; margin: 0; max-width: 18ch; }
.masthead .lead { color: var(--muted); max-width: 60ch; margin: 1rem 0 0; font-size: 1.05em; }
.meta { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: 1.25rem; padding: 0; list-style: none; }
.meta li { font: 500 .78rem/1 var(--font-mono); padding: .45rem .65rem; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); background: var(--surface); }

/* main tabs */
.bar { position: sticky; top: 0; z-index: 20; background: color-mix(in srgb, var(--paper) 88%, transparent); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); }
.tabs { display: flex; gap: .25rem; overflow-x: auto; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab {
  position: relative; flex: none; border: 0; background: none; cursor: pointer;
  font: 500 .95rem/1 var(--font-sans); color: var(--muted); padding: 1.15rem .85rem 1.05rem; white-space: nowrap;
  transition: color var(--duration) var(--ease);
}
.tab::after { content: ""; position: absolute; left: .85rem; right: .85rem; bottom: -1px; height: 3px; background: var(--accent); border-radius: 3px 3px 0 0; transform: scaleX(0); transform-origin: left; transition: transform var(--duration) var(--ease); }
.tab:hover { color: var(--ink); }
.tab[aria-selected="true"] { color: var(--ink); font-weight: 600; }
.tab[aria-selected="true"]::after { transform: scaleX(1); }

/* sub tabs */
main { padding-bottom: 4rem; }
.panel { padding-top: 1.25rem; }
.topic-title { font: 600 .78rem/1.2 var(--font-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); margin: .25rem 0 .75rem; }
.topic-note { margin: 0 0 1rem; padding: .85rem 1rem; border: 1px dashed var(--line); border-radius: 10px; color: var(--muted); font-size: var(--text-small); max-width: var(--measure); }
.topic-note::before { content: "Требование кейса · "; font: 500 .75rem var(--font-mono); text-transform: uppercase; letter-spacing: .08em; color: var(--accent); }
.subtabs {
  position: sticky; top: var(--bar-h); z-index: 10; display: flex; gap: .4rem; overflow-x: auto; scrollbar-width: none;
  padding: .75rem 0; margin-bottom: .5rem; background: var(--paper);
}
.subtabs::-webkit-scrollbar { display: none; }
.subtab {
  flex: none; cursor: pointer; white-space: nowrap; font: 500 .86rem/1 var(--font-sans); color: var(--ink);
  padding: .6rem .9rem; border-radius: 999px; border: 1px solid var(--line); background: var(--surface);
  transition: background var(--duration) var(--ease), color var(--duration) var(--ease), border-color var(--duration) var(--ease), transform var(--duration) var(--ease);
}
.subtab:hover { border-color: var(--accent); }
